CREATE TABLE `shared_only_recovery_installation` (
	`id` integer PRIMARY KEY NOT NULL,
	`descriptor` text NOT NULL,
	`destination_identity` text NOT NULL,
	`installed_at` integer NOT NULL,
	CONSTRAINT "shared_only_recovery_installation_identity" CHECK(json_valid("shared_only_recovery_installation"."destination_identity") AND json_type("shared_only_recovery_installation"."destination_identity",'$.workspaceId') IS 'text' AND json_type("shared_only_recovery_installation"."destination_identity",'$.deviceId') IS 'text' AND json_type("shared_only_recovery_installation"."destination_identity",'$.epochId') IS 'text' AND json_type("shared_only_recovery_installation"."destination_identity",'$.checkpointId') IS 'text' AND json_type("shared_only_recovery_installation"."destination_identity",'$.schemaId') IS 'text' AND json_extract("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.binding.localCheckpoint.identity.workspaceId') IS json_extract("shared_only_recovery_installation"."destination_identity",'$.workspaceId') AND json_extract("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.binding.localCheckpoint.identity.epochId') IS json_extract("shared_only_recovery_installation"."destination_identity",'$.epochId') AND json_extract("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.binding.localCheckpoint.identity.checkpointId') IS json_extract("shared_only_recovery_installation"."destination_identity",'$.checkpointId') AND json_extract("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.binding.localCheckpoint.identity.schemaId') IS json_extract("shared_only_recovery_installation"."destination_identity",'$.schemaId')),
	CONSTRAINT "shared_only_recovery_installation_singleton" CHECK("shared_only_recovery_installation"."id" IS 1),
	CONSTRAINT "shared_only_recovery_installation_time" CHECK(typeof("shared_only_recovery_installation"."installed_at")='integer' AND "shared_only_recovery_installation"."installed_at">=0),
	CONSTRAINT "shared_only_recovery_installation_descriptor" CHECK(json_valid("shared_only_recovery_installation"."descriptor") AND json_type("shared_only_recovery_installation"."descriptor",'$.version') IS 'integer' AND json_extract("shared_only_recovery_installation"."descriptor",'$.version') IS 1 AND json_type("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.version') IS 'integer' AND json_extract("shared_only_recovery_installation"."descriptor",'$.runAssetCheckpoint.version') IS 1 AND json_type("shared_only_recovery_installation"."descriptor",'$.byteLength') IS 'integer' AND json_extract("shared_only_recovery_installation"."descriptor",'$.byteLength') BETWEEN 1 AND 9007199254740991 AND json_type("shared_only_recovery_installation"."descriptor",'$.sha256') IS 'text' AND length(json_extract("shared_only_recovery_installation"."descriptor",'$.sha256')) IS 64 AND json_extract("shared_only_recovery_installation"."descriptor",'$.sha256') NOT GLOB '*[^0-9a-f]*')
);

